    import heapq

def isValidCell(i, j, n):
    return 0 <= i < n and 0 <= j < n

def minimumCostPath(grid):
    n = len(grid)

    # Min heap to implement Dijkstra
    pq = [(grid[0][0], 0, 0)]

    cost = [[float('inf')] * n for _ in range(n)]
    cost[0][0] = grid[0][0]

    # Four possible directions
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while pq:
        currCost, i, j = heapq.heappop(pq)

        # Skip outdated entries
        if currCost != cost[i][j]:
            continue

        # Check all four neighbours
        for di, dj in directions:
            x = i + di
            y = j + dj

            if (isValidCell(x, y, n) and
                    cost[i][j] + grid[x][y] < cost[x][y]):

                cost[x][y] = cost[i][j] + grid[x][y]
                heapq.heappush(pq, (cost[x][y], x, y))

    return cost[n - 1][n - 1]


