        int[,] dir = {
            {-1, 0},
            {1, 0},
            {0, -1},
            {0, 1}
        };

        pq.Add((grid[0, 0], 0, 0));

        while (pq.Count > 0)
        {
            var top = pq.Min;
            pq.Remove(top);

            int i = top.x;
            int j = top.y;

            // Check all four neighbours
            for (int d = 0; d < 4; d++)
            {
                int x = i + dir[d, 0];
                int y = j + dir[d, 1];

                if (isValidCell(x, y, n) &&
                    cost[i, j] + grid[x, y] < cost[x, y])
                {
                    cost[x, y] = cost[i, j] + grid[x, y];
                    pq.Add((cost[x, y], x, y));
                }
            }
        }

        return cost[n - 1, n - 1];
    }

