}


            JavaScript

    function comparator(a, b) {
    return a[0] - b[0];
}

class PriorityQueue {
    constructor(compare) {
        this.heap = [];
        this.compare = compare;
    }

    enqueue(value) {
        this.heap.push(value);
        this.bubbleUp();
    }

    bubbleUp() {
        let index = this.heap.length - 1;

        while (index > 0) {
            let parent = Math.floor((index - 1) / 2);

            if (this.compare(this.heap[index], this.heap[parent]) >= 0)
                break;

            [this.heap[index], this.heap[parent]] =
                [this.heap[parent], this.heap[index]];

            index = parent;
        }
    }

    dequeue() {
        let top = this.heap[0];
        let last = this.heap.pop();

        if (this.heap.length > 0) {
            this.heap[0] = last;
            this.sinkDown(0);
        }

        return top;
    }

    sinkDown(index) {
        let left = 2 * index + 1;
        let right = 2 * index + 2;
        let smallest = index;

        if (left < this.heap.length &&
            this.compare(this.heap[left], this.heap[smallest]) < 0) {
            smallest = left;
        }

        if (right < this.heap.length &&
            this.compare(this.heap[right], this.heap[smallest]) < 0) {
            smallest = right;
        }

        if (smallest !== index) {
            [this.heap[index], this.heap[smallest]] =
                [this.heap[smallest], this.heap[index]];

            this.sinkDown(smallest);
        }
    }

    isEmpty() {
        return this.heap.length === 0;
    }
}

class Solution {
    minimumCostPath(grid, n) {
        let cost = Array.from(
            { length: n },
            () => Array(n).fill(Infinity)
        );

        cost[0][0] = grid[0][0];

        // Four possible directions
        let dir = [
            [-1, 0],
            [1, 0],
            [0, -1],
            [0, 1]
        ];

        let pq = new PriorityQueue(comparator);
        pq.enqueue([grid[0][0], 0, 0]);

        while (!pq.isEmpty()) {
            let [currCost, i, j] = pq.dequeue();

            // Skip outdated entries
            if (currCost !== cost[i][j])
                continue;

            for (let d of dir) {
                let x = i + d[0];
                let y = j + d[1];

                if (x >= 0 && x < n && y >= 0 && y < n &&
                    cost[i][j] + grid[x][y] < cost[x][y]) {

                    cost[x][y] = cost[i][j] + grid[x][y];
                    pq.enqueue([cost[x][y], x, y]);
                }
            }
        }

        return cost[n - 1][n - 1];
    }
}

Output43Why dynamic programming cannot be used?Dynamic programming solution discussed in Min Cost Path with 3 Moves fails here because allowing movement in all four directions creates cycles where cells can be revisited, breaking the optimal substructure assumption. This means the cost to reach a cell from a given cell isn't fixed but depends on the entire path.
